# src/modeling/disaster_prediction.py
"""
Disaster Prediction Engine (SIH Module 2).

This is the ONLY module in the platform that uses machine learning, per the project's AI
Usage Policy. It predicts *future* disruption probability. It does not calculate accessibility
scores, apply business rules, select routes, or verify incidents — those stay deterministic
and live in other modules.

Design constraints honoured here:
  * Explainable — Random Forest with reported feature importances and per-prediction driver
    attribution, not a black box.
  * Auditable — training data is generated by an explicit, documented, seeded process
    (see `generate_training_data`), so any result can be reproduced exactly.
  * Replaceable — everything goes through the `DisasterPredictor` interface. Swapping in a
    model trained on real historical disaster records means implementing the same two methods.
  * Isolated — routing and accessibility code never import this module directly; a service
    layer passes its *outputs* in as plain numbers.

IMPORTANT — about the training data:
The models below are trained on SYNTHETIC data generated from hand-written domain rules
(steeper slope + heavier rain => more landslide risk, etc.). That means the model learns the
rules we encoded, not real-world ground truth. It demonstrates the full ML pipeline
(features -> training -> probability -> explanation) and is honest scaffolding for a real
model, but its probabilities must NOT be presented as validated real-world forecasts. To make
this real, retrain `generate_training_data`'s output against actual historical event records
(GSI landslide inventory, CWC/ASDMA flood records, IMD rainfall archives).
"""

from __future__ import annotations

import logging
import math
import os
import random
from dataclasses import dataclass
from typing import Optional

logger = logging.getLogger("disaster_prediction")

FEATURE_NAMES = [
    "rainfall_mm_24h",
    "forecast_rainfall_mm_48h",
    "slope_gradient_deg",
    "elevation_m",
    "historical_landslides_5y",
    "historical_floods_5y",
    "road_vulnerability_index",
    "recent_incident_count",
]

# Fixed seed so training data — and therefore every prediction — is reproducible.
TRAINING_SEED = 20260101
TRAINING_SAMPLES = 4000


@dataclass(frozen=True)
class DisasterPrediction:
    flood_probability: float
    landslide_probability: float
    combined_disruption_probability: float
    model_type: str
    top_drivers: list
    features: dict


def _sigmoid(x: float) -> float:
    return 1 / (1 + math.exp(-x))


def _landslide_latent(f: dict) -> float:
    """Domain rule used to LABEL synthetic training data (not used at prediction time).

    Encodes: landslides are driven mainly by slope and saturating rainfall, amplified by
    a corridor's own history and by fragile road infrastructure.
    """
    return (
        0.055 * f["slope_gradient_deg"]
        + 0.011 * f["rainfall_mm_24h"]
        + 0.008 * f["forecast_rainfall_mm_48h"]
        + 0.075 * f["historical_landslides_5y"]
        + 0.014 * f["road_vulnerability_index"]
        + 0.0004 * f["elevation_m"]
        + 0.10 * f["recent_incident_count"]
        - 4.6
    )


def _flood_latent(f: dict) -> float:
    """Domain rule used to LABEL synthetic training data (not used at prediction time).

    Encodes: floods are driven by rainfall on low-lying, flood-experienced terrain — steep
    high ground drains and is comparatively safer.
    """
    return (
        0.013 * f["rainfall_mm_24h"]
        + 0.012 * f["forecast_rainfall_mm_48h"]
        + 0.10 * f["historical_floods_5y"]
        + 0.010 * f["road_vulnerability_index"]
        - 0.0022 * f["elevation_m"]
        - 0.030 * f["slope_gradient_deg"]
        + 0.08 * f["recent_incident_count"]
        - 2.4
    )


def generate_training_data(n_samples: int = TRAINING_SAMPLES, seed: int = TRAINING_SEED):
    """Generate the synthetic labelled dataset the models train on.

    Feature ranges are drawn to cover NER-plausible terrain and monsoon conditions. Labels
    are Bernoulli draws from the documented latent rules above, so the data carries genuine
    noise rather than being perfectly separable (a perfectly separable set would produce a
    misleadingly confident model).
    """
    rng = random.Random(seed)
    X, y_flood, y_landslide = [], [], []

    for _ in range(n_samples):
        f = {
            "rainfall_mm_24h": rng.uniform(0, 200),
            "forecast_rainfall_mm_48h": rng.uniform(0, 260),
            "slope_gradient_deg": rng.uniform(1, 35),
            "elevation_m": rng.uniform(20, 2000),
            "historical_landslides_5y": rng.uniform(0, 20),
            "historical_floods_5y": rng.uniform(0, 14),
            "road_vulnerability_index": rng.uniform(10, 95),
            "recent_incident_count": rng.uniform(0, 6),
        }
        p_ls = _sigmoid(_landslide_latent(f))
        p_fl = _sigmoid(_flood_latent(f))
        X.append([f[name] for name in FEATURE_NAMES])
        y_landslide.append(1 if rng.random() < p_ls else 0)
        y_flood.append(1 if rng.random() < p_fl else 0)

    return X, y_flood, y_landslide


class DisasterPredictor:
    """Interface. Implement these two methods to swap in a real model."""

    def predict(self, features: dict) -> DisasterPrediction:
        raise NotImplementedError

    def feature_importances(self) -> dict:
        raise NotImplementedError

    def predict_many(self, feature_dicts: list) -> list:
        """Predict for several segments at once.

        The whole network is assessed together — every dashboard load, every map refresh and
        every route plan needs all N segments — so the natural unit of work is the batch, not
        the row. A tree ensemble pays a fixed per-call cost (argument validation, array
        allocation, tree traversal setup) that dwarfs the arithmetic for a single row, which
        is why calling `predict` N times is far slower than one call with N rows.

        The default implementation is the honest fallback for any predictor that has no
        batch path of its own; subclasses that can do better should override it.
        """
        return [self.predict(f) for f in feature_dicts]


# Relative magnitudes of the latent-rule coefficients. A module constant rather than a dict
# rebuilt per prediction, because driver attribution asks for it on every single call.
_HEURISTIC_IMPORTANCES = {
    "slope_gradient_deg": 0.24,
    "rainfall_mm_24h": 0.18,
    "forecast_rainfall_mm_48h": 0.15,
    "historical_landslides_5y": 0.14,
    "historical_floods_5y": 0.11,
    "road_vulnerability_index": 0.09,
    "recent_incident_count": 0.06,
    "elevation_m": 0.03,
}


class HeuristicDisasterPredictor(DisasterPredictor):
    """Deterministic fallback used when scikit-learn is unavailable.

    Applies the same documented latent rules directly instead of learning them. Clearly
    reported as `model_type="heuristic_fallback"` so a heuristic result is never mistaken
    for a model result.
    """

    def predict(self, features: dict) -> DisasterPrediction:
        f = _normalise_features(features)
        p_flood = round(_sigmoid(_flood_latent(f)), 4)
        p_landslide = round(_sigmoid(_landslide_latent(f)), 4)
        combined = round(1 - (1 - p_flood) * (1 - p_landslide), 4)
        return DisasterPrediction(
            flood_probability=p_flood,
            landslide_probability=p_landslide,
            combined_disruption_probability=combined,
            model_type="heuristic_fallback",
            top_drivers=_attribute_drivers(f, self.feature_importances()),
            features=f,
        )

    def feature_importances(self) -> dict:
        # Relative magnitudes of the latent-rule coefficients, normalised for reporting.
        return dict(_HEURISTIC_IMPORTANCES)


class RandomForestDisasterPredictor(DisasterPredictor):
    """Random Forest predictor (spec: Random Forest or XGBoost; deep learning avoided).

    Trains two independent binary classifiers — one for flood, one for landslide — and
    combines them assuming independence:
        P(disruption) = 1 - (1 - P(flood)) * (1 - P(landslide))
    That independence assumption is a simplification: in reality heavy rain drives both, so
    the combined figure is best read as an upper-ish bound on "something goes wrong here".
    """

    def __init__(self, model_dir: Optional[str] = None, auto_train: bool = True):
        from sklearn.ensemble import RandomForestClassifier  # imported lazily on purpose

        if model_dir is None:
            model_dir = os.path.join(
                os.path.dirname(os.path.abspath(__file__)), "..", "..", "data", "processed", "models"
            )
        self.model_dir = os.path.abspath(model_dir)
        self._RandomForestClassifier = RandomForestClassifier
        self.flood_model = None
        self.landslide_model = None
        # Feature importances are a property of the fitted forest, so they are the same for
        # every prediction — but scikit-learn recomputes them across all 120 trees on each
        # attribute access, and driver attribution asks for them once per prediction. Held
        # here and cleared on retrain.
        self._importances_cache = None
        if auto_train:
            self._load_or_train()

    def _model_paths(self):
        return (
            os.path.join(self.model_dir, "flood_rf.joblib"),
            os.path.join(self.model_dir, "landslide_rf.joblib"),
        )

    def _load_or_train(self):
        import joblib

        flood_path, landslide_path = self._model_paths()
        if os.path.exists(flood_path) and os.path.exists(landslide_path):
            try:
                self.flood_model = joblib.load(flood_path)
                self.landslide_model = joblib.load(landslide_path)
                self._importances_cache = None
                logger.info("Loaded persisted disaster prediction models.")
                return
            except Exception as e:  # corrupt/incompatible artefact -> retrain rather than crash
                logger.warning(f"Could not load persisted models ({e}); retraining.")
        self.train()

    def train(self, persist: bool = True):
        X, y_flood, y_landslide = generate_training_data()

        common = dict(n_estimators=120, max_depth=8, min_samples_leaf=10, random_state=TRAINING_SEED)
        self.flood_model = self._RandomForestClassifier(**common).fit(X, y_flood)
        self.landslide_model = self._RandomForestClassifier(**common).fit(X, y_landslide)
        self._importances_cache = None
        logger.info("Trained disaster prediction models on synthetic data.")

        if persist:
            try:
                import joblib

                os.makedirs(self.model_dir, exist_ok=True)
                flood_path, landslide_path = self._model_paths()
                joblib.dump(self.flood_model, flood_path)
                joblib.dump(self.landslide_model, landslide_path)
            except Exception as e:
                logger.warning(f"Could not persist models: {e}")

    @staticmethod
    def _positive_class_column(model):
        """Index of the "event happened" column in predict_proba's output.

        A forest fitted on a label set that happened to contain only one class has a single
        probability column, and indexing [1] would raise. Reading the position of class 1 out
        of `classes_` is correct in every case and costs nothing.
        """
        classes = list(getattr(model, "classes_", [0, 1]))
        return classes.index(1) if 1 in classes else len(classes) - 1

    def _assemble(self, f: dict, p_flood: float, p_landslide: float) -> DisasterPrediction:
        combined = round(1 - (1 - p_flood) * (1 - p_landslide), 4)
        return DisasterPrediction(
            flood_probability=p_flood,
            landslide_probability=p_landslide,
            combined_disruption_probability=combined,
            model_type="random_forest",
            top_drivers=_attribute_drivers(f, self.feature_importances()),
            features=f,
        )

    def predict(self, features: dict) -> DisasterPrediction:
        return self.predict_many([features])[0]

    def predict_many(self, feature_dicts: list) -> list:
        """One forest traversal for the whole network instead of one per segment.

        Assessing the NER network means predicting for every segment at once. Feeding the
        rows to scikit-learn as a single matrix turns N round trips through the estimator's
        validation and allocation machinery into one, which is where nearly all the time in
        an N-row prediction actually goes.
        """
        normalised = [_normalise_features(f) for f in feature_dicts]
        if not normalised:
            return []

        rows = [[f[name] for name in FEATURE_NAMES] for f in normalised]
        flood_col = self._positive_class_column(self.flood_model)
        landslide_col = self._positive_class_column(self.landslide_model)
        flood_probs = self.flood_model.predict_proba(rows)
        landslide_probs = self.landslide_model.predict_proba(rows)

        return [
            self._assemble(
                f,
                round(float(flood_probs[i][flood_col]), 4),
                round(float(landslide_probs[i][landslide_col]), 4),
            )
            for i, f in enumerate(normalised)
        ]

    def feature_importances(self) -> dict:
        """Mean of the two forests' importances, per feature. Computed once per fit."""
        if self._importances_cache is None:
            self._importances_cache = {
                name: round(float((fi_flood + fi_ls) / 2), 4)
                for name, fi_flood, fi_ls in zip(
                    FEATURE_NAMES,
                    self.flood_model.feature_importances_,
                    self.landslide_model.feature_importances_,
                )
            }
        return self._importances_cache


def _normalise_features(features: dict) -> dict:
    """Fill in missing features with neutral defaults and coerce to float.

    Missing data is expected in the field (a segment with no weather station, an incident
    count that hasn't synced yet), so this degrades gracefully instead of raising.
    """
    defaults = {
        "rainfall_mm_24h": 0.0,
        "forecast_rainfall_mm_48h": 0.0,
        "slope_gradient_deg": 5.0,
        "elevation_m": 100.0,
        "historical_landslides_5y": 0.0,
        "historical_floods_5y": 0.0,
        "road_vulnerability_index": 40.0,
        "recent_incident_count": 0.0,
    }
    out = {}
    for name in FEATURE_NAMES:
        value = features.get(name, defaults[name])
        try:
            out[name] = float(value)
        except (TypeError, ValueError):
            out[name] = defaults[name]
    return out


def _attribute_drivers(features: dict, importances: dict, top_n: int = 3) -> list:
    """Per-prediction explanation: which inputs pushed this particular prediction up.

    This is importance-weighted attribution (feature importance x how extreme this feature's
    value is relative to its plausible range) — a transparent approximation, NOT SHAP values.
    It answers "what is unusual about this segment that the model cares about", which is what
    an operator or judge actually needs to see next to a probability.
    """
    ranges = {
        "rainfall_mm_24h": 200.0,
        "forecast_rainfall_mm_48h": 260.0,
        "slope_gradient_deg": 35.0,
        "elevation_m": 2000.0,
        "historical_landslides_5y": 20.0,
        "historical_floods_5y": 14.0,
        "road_vulnerability_index": 95.0,
        "recent_incident_count": 6.0,
    }
    scored = []
    for name, value in features.items():
        span = ranges.get(name, 1.0) or 1.0
        intensity = min(1.0, max(0.0, value / span))
        scored.append(
            {
                "feature": name,
                "value": round(value, 2),
                "contribution": round(importances.get(name, 0.0) * intensity, 4),
            }
        )
    scored.sort(key=lambda d: d["contribution"], reverse=True)
    return scored[:top_n]


def get_default_predictor() -> DisasterPredictor:
    """Return a Random Forest predictor, falling back to the heuristic if sklearn is absent.

    Kept as a factory so callers never hard-depend on scikit-learn being installed — the
    platform stays functional (with clearly-labelled degraded predictions) if it isn't.
    """
    try:
        return RandomForestDisasterPredictor()
    except ImportError:
        logger.warning("scikit-learn unavailable; using heuristic fallback predictor.")
        return HeuristicDisasterPredictor()
    except Exception as e:
        logger.warning(f"Could not initialise RandomForest predictor ({e}); using heuristic fallback.")
        return HeuristicDisasterPredictor()
